import random, time
import anthropic

client = anthropic.Anthropic(max_retries=0)  # exactly one layer owns retries: this one
PRIMARY = "claude-sonnet-4-5"                # example ids: any two models
FALLBACK = "claude-haiku-4-5"
TRANSIENT = {408, 429, 500, 502, 503, 504, 529}

def full_jitter(attempt: int, base: float = 0.5, cap: float = 20.0) -> float:
    # Uniform in [0, base*2^n]: de-synchronizes clients that failed together
    return random.uniform(0, min(cap, base * 2 ** attempt))

def ask(messages, model=PRIMARY, attempts=3, deadline_s=45.0):
    start = time.monotonic()
    for n in range(attempts):
        try:
            return client.messages.create(model=model, max_tokens=1024,
                                          messages=messages, timeout=30.0)
        except anthropic.APIStatusError as e:
            if e.status_code not in TRANSIENT:
                raise                                   # 400/401/403: permanent
            hint = e.response.headers.get("retry-after")
            wait = float(hint) if hint else full_jitter(n)  # server knows best
        except anthropic.APIConnectionError:            # also covers timeouts
            wait = full_jitter(n)
        if n + 1 == attempts or time.monotonic() - start + wait > deadline_s:
            break                                       # out of attempts or time
        time.sleep(wait)
    if model != FALLBACK:                               # degrade instead of failing
        return ask(messages, FALLBACK, attempts=2, deadline_s=15.0)
    raise RuntimeError("primary and fallback both unavailable")
